import java.util.Scanner;

public class Main{

    public static String replaceNumber(String s){
        int count = 0;// 原来统计字符串s中的数字字符
        int sOldSize = s.length();
        for(int i = 0; i < sOldSize; i++){
            if(Character.isDigit(s.charAt(i))){
                count++;
            }
        }
        // 扩充字符串s的大小
        char[] newS = new char[sOldSize + count * 5];
        int sNewSize = newS.length;
        // 将旧字符串内容填入新数组中
        System.arraycopy(s.toCharArray(), 0, newS, 0, sOldSize);
        // 从后向前将空格填充为number
        for(int i = sOldSize - 1, j = sNewSize -1; i < j; j--, i--){
            if(!Character.isDigit(newS[i])){// 判断是否为数字
                newS[j] = newS[i];
            }
            else{
                newS[j] = 'r';
                newS[j-1] = 'e';
                newS[j-2] = 'b';
                newS[j-3] = 'm';
                newS[j-4] = 'u';
                newS[j-5] = 'n';
                j -= 5;               
            }
        }
        return new String(newS);
    };

    public static void main(String[] args){
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        System.out.println(replaceNumber(s));
        scanner.close();
    }
}


